"""
demo.py -- Numerical demonstrations of the GL(1) Langlands correspondence
(cyclotomic case over the rationals).

This script makes the abstract theorems concrete and checkable:

  * artinIso                 : Gal(Q(zeta_n)/Q)  ==  (Z/nZ)^x        (relabeling)
  * langlandsGL1             : Dirichlet chars mod n  ==  1-dim Galois reps
  * card_dirichlet_eq_totient: #(Dirichlet chars mod n) = phi(n)
  * card_galois_reps_eq_totient: #(1-dim Galois reps) = phi(n)
  * card_galois_reps_prime   : for prime p, that count = p - 1
  * heckeFactorization       : chars mod m*k  ==  chars mod m  x  chars mod k  (gcd=1)

Everything is self-contained: characters are represented exactly as integer
"exponent vectors" against a chosen basis of the unit group, so all checks are
exact (no floating-point error).  We also expose complex-valued evaluation.

Run:  python3 demo.py
"""

from __future__ import annotations

import cmath
import math
from itertools import product
from typing import Dict, List, Tuple

# ---------------------------------------------------------------------------
# Elementary number theory
# ---------------------------------------------------------------------------


def euler_totient(n: int) -> int:
    """Euler's totient phi(n): count of 1 <= a <= n with gcd(a, n) = 1."""
    return sum(1 for a in range(1, n + 1) if math.gcd(a, n) == 1)


def unit_group(n: int) -> List[int]:
    """The elements of (Z/nZ)^x, as integers in [1, n)."""
    return [a for a in range(1, n) if math.gcd(a, n) == 1]


# ---------------------------------------------------------------------------
# Structure of the finite abelian group (Z/nZ)^x as a product of cyclic groups
# ---------------------------------------------------------------------------


def _element_order(a: int, n: int) -> int:
    """Multiplicative order of a modulo n."""
    order, cur = 1, a % n
    while cur != 1:
        cur = (cur * a) % n
        order += 1
    return order


def cyclic_decomposition(n: int) -> Tuple[List[int], List[int]]:
    """
    Return (generators, orders) realizing (Z/nZ)^x as an INTERNAL DIRECT PRODUCT
        (Z/nZ)^x = <g_1> x ... x <g_r>,
    with g_i of order orders[i] and prod(orders) = phi(n).

    Construction: repeatedly adjoin the unit of largest order whose cyclic
    subgroup meets the already-generated subgroup trivially (a direct factor).
    An element of maximal order in a finite abelian group always spans a direct
    factor, so this terminates with an exact internal direct product.
    """
    units = unit_group(n)
    target = euler_totient(n)
    if target == 1:
        return [], []

    generators: List[int] = []
    orders: List[int] = []
    subgroup = {1}

    def span_with(gens: List[int], ords: List[int]) -> set[int]:
        elems = {1}
        for exps in product(*[range(o) for o in ords]):
            val = 1
            for g, e in zip(gens, exps):
                val = (val * pow(g, e, n)) % n
            elems.add(val)
        return elems

    while len(subgroup) < target:
        best_g, best_o = None, 0
        for g in units:
            o = _element_order(g, n)
            # Independence: no nontrivial power of g lies in the current subgroup,
            # i.e. <g> ∩ subgroup = {1}, so adjoining g is a direct factor.
            val, independent = 1, True
            for _ in range(1, o):
                val = (val * g) % n
                if val in subgroup:
                    independent = False
                    break
            if independent and o > best_o:
                best_o, best_g = o, g
        assert best_g is not None, "no independent generator found"
        generators.append(best_g)
        orders.append(best_o)
        subgroup = span_with(generators, orders)

    return generators, orders


# ---------------------------------------------------------------------------
# Dirichlet characters mod n, represented exactly by exponent vectors
# ---------------------------------------------------------------------------


class DirichletCharacter:
    """
    A Dirichlet character mod n.  Internally stored as a tuple of integers
    `a = (a_1, ..., a_r)` meaning: on the i-th cyclic generator g_i (order d_i),
    the character takes the value exp(2*pi*i * a_i / d_i).

    Values on arbitrary units are computed by expressing the unit in the basis.
    """

    def __init__(self, n: int, exps: Tuple[int, ...],
                 generators: List[int], orders: List[int]) -> None:
        self.n = n
        self.exps = tuple(e % o for e, o in zip(exps, orders)) if orders else ()
        self.generators = generators
        self.orders = orders
        self._discrete_log = _discrete_log_table(n, generators, orders)

    def __call__(self, a: int) -> complex:
        """Evaluate the character at integer a (0 if gcd(a, n) != 1)."""
        a %= self.n
        if math.gcd(a, self.n) != 1:
            return 0.0 + 0.0j
        coords = self._discrete_log[a]
        phase = 0.0
        for ai, ci, di in zip(self.exps, coords, self.orders):
            phase += ai * ci / di
        return cmath.exp(2j * math.pi * phase)

    def __mul__(self, other: "DirichletCharacter") -> "DirichletCharacter":
        """Pointwise product of characters (the group law)."""
        new_exps = tuple(x + y for x, y in zip(self.exps, other.exps))
        return DirichletCharacter(self.n, new_exps, self.generators, self.orders)

    def __eq__(self, other: object) -> bool:
        return (isinstance(other, DirichletCharacter)
                and self.n == other.n and self.exps == other.exps)

    def __hash__(self) -> int:
        return hash((self.n, self.exps))

    def __repr__(self) -> str:
        return f"Char(mod {self.n}, exps={self.exps})"


def _discrete_log_table(n: int, generators: List[int],
                        orders: List[int]) -> Dict[int, Tuple[int, ...]]:
    """Map each unit a to its coordinate vector (c_1, ..., c_r) in the basis."""
    table: Dict[int, Tuple[int, ...]] = {}
    if not generators:
        table[1] = ()
        return table
    for exps in product(*[range(o) for o in orders]):
        val = 1
        for g, e in zip(generators, exps):
            val = (val * pow(g, e, n)) % n
        table[val] = exps
    return table


def all_dirichlet_characters(n: int) -> List[DirichletCharacter]:
    """Enumerate every Dirichlet character mod n (there are phi(n) of them)."""
    generators, orders = cyclic_decomposition(n)
    if not orders:
        return [DirichletCharacter(n, (), generators, orders)]
    chars = []
    for exps in product(*[range(o) for o in orders]):
        chars.append(DirichletCharacter(n, exps, generators, orders))
    return chars


# ---------------------------------------------------------------------------
# The Artin map and the Langlands GL(1) correspondence
# ---------------------------------------------------------------------------


def artin_exponent(sigma_k: int, n: int) -> int:
    """
    artinIso:  Gal(Q(zeta_n)/Q) -> (Z/nZ)^x.

    We model a Galois automorphism sigma by the exponent k (coprime to n) with
    sigma(zeta_n) = zeta_n^k.  The Artin map is then the identity 'k |-> k';
    this function records that identification explicitly.
    """
    assert math.gcd(sigma_k, n) == 1, "automorphism exponent must be a unit"
    return sigma_k % n


def galois_representation(chi: DirichletCharacter):
    """
    langlandsGL1(chi): the 1-dim Galois rep  sigma |-> chi(artin_exponent(sigma)).
    Returns a function on automorphism-exponents k.
    """
    n = chi.n

    def rho(sigma_k: int) -> complex:
        return chi(artin_exponent(sigma_k, n))

    return rho


# ---------------------------------------------------------------------------
# Verifications of the theorems
# ---------------------------------------------------------------------------


def verify_totient_count(n: int) -> bool:
    """card_dirichlet_eq_totient / card_galois_reps_eq_totient for modulus n."""
    chars = all_dirichlet_characters(n)
    phi = euler_totient(n)
    # Distinct as functions:
    assert len({c.exps for c in chars}) == len(chars)
    return len(chars) == phi


def verify_prime_count(p: int) -> bool:
    """card_galois_reps_prime: count = p - 1 for prime p."""
    return len(all_dirichlet_characters(p)) == p - 1


def verify_group_isomorphism(n: int, samples: int = 6) -> bool:
    """
    langlandsGL1 is a GROUP isomorphism, not just a bijection:
    rho(chi1 * chi2) = rho(chi1) * rho(chi2)  pointwise on the Galois group.
    """
    chars = all_dirichlet_characters(n)
    units = unit_group(n)
    chars = chars[:samples] if len(chars) > samples else chars
    for c1 in chars:
        for c2 in chars:
            r_prod = galois_representation(c1 * c2)
            r1, r2 = galois_representation(c1), galois_representation(c2)
            for k in units:
                lhs = r_prod(k)
                rhs = r1(k) * r2(k)
                if abs(lhs - rhs) > 1e-9:
                    return False
    return True


def verify_hecke_factorization(m: int, k: int) -> bool:
    """
    heckeFactorization: for gcd(m, k) = 1,
    #chars(m*k) = #chars(m) * #chars(k)   (cardinality form of the CRT split).
    Also checks the totient is multiplicative, consistent with the iso.
    """
    assert math.gcd(m, k) == 1
    lhs = len(all_dirichlet_characters(m * k))
    rhs = len(all_dirichlet_characters(m)) * len(all_dirichlet_characters(k))
    tot = euler_totient(m * k) == euler_totient(m) * euler_totient(k)
    return lhs == rhs and tot


# ---------------------------------------------------------------------------
# Main driver
# ---------------------------------------------------------------------------


def main() -> None:
    print("=" * 70)
    print("GL(1) Langlands correspondence (cyclotomic case over Q) -- demo")
    print("=" * 70)

    print("\n[1] Totient counts: #Dirichlet chars = #Galois reps = phi(n)")
    print(f"    {'n':>4} | {'phi(n)':>7} | {'#chars':>7} | ok")
    print("    " + "-" * 34)
    for n in range(1, 21):
        chars = all_dirichlet_characters(n)
        phi = euler_totient(n)
        ok = verify_totient_count(n)
        print(f"    {n:>4} | {phi:>7} | {len(chars):>7} | {ok}")

    print("\n[2] Prime case: count = p - 1  (card_galois_reps_prime)")
    for p in [2, 3, 5, 7, 11, 13, 101]:
        ok = verify_prime_count(p)
        print(f"    p = {p:>4}:  #reps = {p - 1:>4}   verified = {ok}")

    print("\n[3] The correspondence is a GROUP isomorphism (rho is multiplicative)")
    for n in [5, 7, 8, 12, 15]:
        ok = verify_group_isomorphism(n)
        print(f"    n = {n:>3}:  rho(c1*c2) = rho(c1)*rho(c2)  ->  {ok}")

    print("\n[4] Hecke / CRT factorization  (heckeFactorization)")
    print("    chars(m*k) = chars(m) x chars(k)  for coprime m, k")
    for m, k in [(3, 5), (4, 9), (5, 7), (8, 9), (3, 11)]:
        ok = verify_hecke_factorization(m, k)
        a, b, c = (len(all_dirichlet_characters(x)) for x in (m, k, m * k))
        print(f"    m={m:>2}, k={k:>2}:  {a} x {b} = {a*b}  ==  {c}  ->  {ok}")

    print("\n[5] Explicit example: the four characters mod 5 and their Galois reps")
    n = 5
    chars = all_dirichlet_characters(n)
    units = unit_group(n)
    print(f"    units of (Z/5Z)^x = {units}")
    for idx, chi in enumerate(chars):
        rho = galois_representation(chi)
        vals = [f"{rho(k).real:+.3f}{rho(k).imag:+.3f}i" for k in units]
        print(f"    rep #{idx}: sigma_k -> " + ", ".join(
            f"k={k}:{v}" for k, v in zip(units, vals)))

    print("\nAll demonstrations completed.")


if __name__ == "__main__":
    main()
